  or exists (
    select
      1
    from
      public.video_edit_version version
    where
      version."assetId" = asset.id
  ) as "edited"
from
  "asset_scan_crop"
  inner join "asset" on "asset"."id" = "asset_scan_crop"."assetId"
  left join "asset_exif" on "asset_exif"."assetId" = "asset"."id"
where
  "asset_scan_crop"."sourceAssetId" = $1::uuid
